// PATCH contract checks
{
  const { ProfileService } = require('../.build/service');
  const fresh = () => new ProfileService({ displayName: 'name', tags: ['a', 'b'] });
  const bad = (input) => assert.throws(() => fresh().patch(input), /^Error: invalid profile$/);

  // Empty object is a no-op
  assert.deepEqual(fresh().patch({}), { displayName: 'name', tags: ['a', 'b'] });

  // displayName
  assert.deepEqual(fresh().patch({ displayName: null }), { displayName: null, tags: ['a', 'b'] });
  assert.deepEqual(fresh().patch({ displayName: '  Ann  ' }), { displayName: 'Ann', tags: ['a', 'b'] });
  assert.deepEqual(fresh().patch({ displayName: 'x'.repeat(40) }), { displayName: 'x'.repeat(40), tags: ['a', 'b'] });
  assert.deepEqual(fresh().patch({ displayName: ' '.repeat(3) + 'y' + ' '.repeat(2) }), { displayName: 'y', tags: ['a', 'b'] });
  bad({ displayName: 'x'.repeat(41) });
  bad({ displayName: '' });
  bad({ displayName: '   ' });
  bad({ displayName: 42 });
  bad({ displayName: true });
  bad({ displayName: undefined });
  bad({ displayName: ['Ann'] });

  // tags
  assert.deepEqual(fresh().patch({ tags: null }), { displayName: 'name', tags: [] });
  assert.deepEqual(fresh().patch({ tags: [] }), { displayName: 'name', tags: [] });
  assert.deepEqual(fresh().patch({ tags: [' a ', 'b', 'c', 'd', 'e'] }), { displayName: 'name', tags: ['a', 'b', 'c', 'd', 'e'] });
  assert.deepEqual(fresh().patch({ tags: ['x'.repeat(12)] }), { displayName: 'name', tags: ['x'.repeat(12)] });
  bad({ tags: ['a', 'b', 'c', 'd', 'e', 'f'] });
  bad({ tags: ['a', ' a '] });            // duplicate after trimming
  bad({ tags: ['  '] });                  // empty after trimming
  bad({ tags: [''] });
  bad({ tags: ['x'.repeat(13)] });
  bad({ tags: [' ' + 'x'.repeat(12) + ' '.repeat(0) + ' '] }); // 12 after trim is fine; keep as valid below
  bad({ tags: [1] });                     // no numeric coercion
  bad({ tags: ['a', null] });
  bad({ tags: 'a' });
  bad({ tags: { 0: 'a', length: 1 } });
  bad({ tags: [, 'a'] });                 // hole
  bad({ tags: Object.assign(['a'], { extra: 'x' }) });

  // Whole-input validation
  bad(null);
  bad([]);
  bad('profile');
  bad(7);
  bad({ displayName: 'ok', color: 'red' }); // unknown key
  bad(Object.assign(Object.create({ inherited: true }), { displayName: 'ok' }));
  bad(Object.assign(Object.create(Array.prototype), { displayName: 'ok' }));
  bad(Object.assign(new (class Foo {})(), { displayName: 'ok' }));
  bad({ get displayName() { return 'ok'; } });
  assert.deepEqual(fresh().patch(Object.assign(Object.create(null), { displayName: 'nullproto' })), { displayName: 'nullproto', tags: ['a', 'b'] });

  // Atomicity: a later invalid field leaves storage untouched
  {
    const svc = fresh();
    assert.throws(() => svc.patch({ displayName: 'new', tags: ['dup', 'dup'] }), /^Error: invalid profile$/);
    assert.deepEqual(svc.profile, { displayName: 'name', tags: ['a', 'b'] });
  }

  // Input is not mutated and caller's array is not stored
  {
    const tags = [' t1 ', 't2'];
    const input = { tags };
    const snapshot = JSON.stringify(input);
    const svc = fresh();
    const result = svc.patch(input);
    assert.equal(JSON.stringify(input), snapshot);
    assert.deepEqual(result.tags, ['t1', 't2']);
    assert.notEqual(result.tags, tags);
    tags.push('later');
    assert.deepEqual(svc.profile.tags, ['t1', 't2']);
  }
}
console.log('patch contract checks passed');
EOF
